struct posix_acl *xfs_acl_from_disk(struct xfs_acl *aclp) {
    int count = aclp->acl_count;
    struct posix_acl *posix_acl;
    struct posix_acl_entry *entry;
    int i;

    if (count < 0 || count > POSIX_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    posix_acl = kmalloc(sizeof(struct posix_acl) + count * sizeof(struct posix_acl_entry), GFP_KERNEL);
    if (!posix_acl)
        return ERR_PTR(-ENOMEM);

    posix_acl->a_count = count;

    entry = posix_acl->a_entries;
    for (i = 0; i < count; i++) {
        switch (aclp->acl_entry[i].e_tag) {
            case XFS_ACL_USER_OBJ:
                entry->e_tag = POSIX_ACL_USER_OBJ;
                break;
            case XFS_ACL_GROUP_OBJ:
                entry->e_tag = POSIX_ACL_GROUP_OBJ;
                break;
            case XFS_ACL_OWNER:
                entry->e_tag = POSIX_ACL_OWNER;
                break;
            case XFS_ACL_EVERYONE:
                entry->e_tag = POSIX_ACL_EVERYONE;
                break;
            default:
                kfree(posix_acl);
                return ERR_PTR(-EINVAL);
        }

        entry->e_perm = aclp->acl_entry[i].e_perm;
        entry++;
    }

    return posix_acl;
}

struct posix_acl *xfs_acl_from_xattr(struct xfs_acl *aclp)
{
    int count = le16_to_cpu(aclp->count);
    struct posix_acl *pacl;
    int i;

    if (count > XFS_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    pacl = posix_acl_alloc(count, GFP_KERNEL);
    if (!pacl)
        return ERR_PTR(-ENOMEM);

    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *e = &aclp->entries[i];
        struct posix_acl_entry *ep = &pacl->a_entries[i];
        int tag;

        tag = le16_to_cpu(e->tag);
        switch (tag) {
        case XFS_ACL_USER_OBJ:
            ep->e_tag = ACL_USER_OBJ;
            break;
        case XFS_ACL_GROUP_OBJ:
            ep->e_tag = ACL_GROUP_OBJ;
            break;
        case XFS_ACL_OWNER:
            ep->e_tag = ACL_OWNER;
            break;
        case XFS_ACL_EVERYONE:
            ep->e_tag = ACL_OTHER;
            break;
        default:
            posix_acl_release(pacl);
            return ERR_PTR(-EINVAL);
        }

        ep->e_perm = le16_to_cpu(e->perm);
    }

    return pacl;
}

struct posix_acl *convert_xfs_acl_to_posix(const struct xfs_acl *aclp)
{
    int count = aclp->acl_count;
    struct posix_acl *acl;
    int i;

    if (count > POSIX_ACL_MAX_ENTRIES)
        return ERR_PTR(-EINVAL);

    acl = kmalloc(sizeof(struct posix_acl) + count * sizeof(struct posix_acl_entry), GFP_KERNEL);
    if (!acl)
        return ERR_PTR(-ENOMEM);

    acl->a_count = count;
    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *entry = &aclp->acl_entry[i];
        struct posix_acl_entry *posix_entry = &acl->a_entries[i];

        switch (entry->e_tag) {
        case XFS_ACL_USER_OBJ:
            posix_entry->e_tag = POSIX_ACL_USER_OBJ;
            break;
        case XFS_ACL_GROUP_OBJ:
            posix_entry->e_tag = POSIX_ACL_GROUP_OBJ;
            break;
        case XFS_ACL_OWNER:
            posix_entry->e_tag = POSIX_ACL_OWNER;
            break;
        case XFS_ACL_EVERYONE:
            posix_entry->e_tag = POSIX_ACL_EVERYONE;
            break;
        default:
            kfree(acl);
            return ERR_PTR(-EINVAL);
        }

        posix_entry->e_perm = entry->e_perm;
    }

    return acl;
}

